 route('GET','/api/v1/admin/auth/invite',ctx=>{const t=useToken('invite',ctx.query.token);const u=db().users.find(x=>x.id===t.userId);return {email:u.email,name:u.name,roles:u.roles.map(r=>D.ROLE_LABELS[r])}});
 route('POST','/api/v1/admin/auth/accept-invite',ctx=>{const t=useToken('invite',ctx.body.token);const problem=S.passwordProblem(ctx.body.password);if(problem)fail(422,'VALIDATION_ERROR',problem,{fields:{password:problem}});if(ctx.body.password!==ctx.body.password2)fail(422,'VALIDATION_ERROR','Las contraseñas no coinciden.',{fields:{password2:'Las contraseñas no coinciden.'}});store.tx(d=>{d.tokens.find(x=>x.hash===t.hash).used=true;const u=d.users.find(x=>x.id===t.userId);u.passHash=S.hashPassword(ctx.body.password);u.status='active';u.emailVerifiedAt=Date.now();D.audit(d,u.id,'staff.invite_accepted','user',u.id,{},ctx.requestId)});return {ok:true}});

