 route('POST','/api/v1/admin/properties',ctx=>{const u=staff(ctx,'internal_contributor');const now=Date.now();let p;store.tx(d=>{const nid=d.meta.nextPropertyId++;p={id:nid,publicId:'SS-'+String(nid).padStart(4,'0'),slug:'borrador-'+nid,title:str(ctx.body.title,140)||'Nueva propiedad',type:'Casa',region:'Región Metropolitana',commune:'',publicLocation:'',exactAddress:'',lat:null,lng:null,rooms:null,baths:null,parking:null,area:null,plot:null,occupancy:'Por confirmar',expenses:null,description:'',media:[],documents:[],legalNotes:'',legalComplete:false,conditions:{opensAt:null,closesAt:null,initialUF:null,incrementUF:50},seo:{title:'',description:''},reviewStatus:'draft',publicStatus:'not_public',version:1,submittedVersion:0,publishedVersion:0,history:[{version:1,at:now,by:u.id,action:'created'}],createdBy:u.id,assignedLegal:null,auctionId:null,createdAt:now,updatedAt:now,publishedAt:null};d.properties.push(p);D.audit(d,u.id,'property.create','property',nid,{},ctx.requestId)});return {property:adminProperty(p,u)}});
 const findProperty=id=>{const p=db().properties.find(x=>x.id===Number(id));if(!p)fail(404,'NOT_FOUND','La propiedad no existe.');return p};
 route('GET','/api/v1/admin/properties/:id',(ctx,{id})=>{const u=staff(ctx,'internal_contributor','legal');return {property:adminProperty(findProperty(id),u),legalUsers:db().users.filter(x=>x.roles.includes('legal')).map(x=>({id:x.id,name:x.name})),communes:require('./semilla.cjs').COMMUNES}});
 const GENERAL=['title','type','commune','exactAddress','rooms','baths','parking','area','plot','occupancy','expenses','description'];
