 function queueWhatsapp(d,{to,text,userId=null,kind='task',taskId=null}){if(!to)return;(d.whatsapp=d.whatsapp||[]).unshift({id:S.id('wa'),to,text,userId,kind,taskId,status:'queued',tries:0,at:Date.now()});if(d.whatsapp.length>800)d.whatsapp.length=800}
