 /* Recordatorios automáticos: 24 horas antes del vencimiento y al vencer, una sola vez cada uno. */
 function taskReminders(){const now=Date.now();const due=(db().tasks||[]).filter(t=>t.dueAt&&['pending','in_progress'].includes(t.status)&&((t.dueAt-now<=86400000&&t.dueAt>now&&!t.remindersSent.includes('24h'))||(t.dueAt<=now&&!t.remindersSent.includes('overdue'))));if(!due.length)return;
  store.tx(d=>{for(const t of due){const x=d.tasks.find(v=>v.id===t.id);const kind=x.dueAt<=now?'overdue':'24h';x.remindersSent.push(kind);if(kind==='overdue'&&!x.remindersSent.includes('24h'))x.remindersSent.push('24h');dispatchTask(d,x,{intro:kind==='overdue'?'Tarea vencida':'Tarea vence en menos de 24 horas',recipients:x.assignees,actor:x.createdBy,channels:x.channels});if(kind==='overdue')dispatchTask(d,x,{intro:'Tarea vencida (asignada por ti)',recipients:[x.createdBy].filter(i=>!x.assignees.includes(i)),actor:x.createdBy,channels:{email:true,whatsapp:false}})}})}
 let sendingWa=false;async function deliverWhatsapp(){if(sendingWa)return;const queue=(db().whatsapp||[]).filter(m=>m.status==='queued'&&m.tries<3).slice(0,20);if(!queue.length)return;sendingWa=true;try{for(const m of queue){let status,error='';try{status=(await WA.deliver(m)).status}catch(err){status='queued';error=err.message}store.tx(d=>{const x=d.whatsapp.find(v=>v.id===m.id);if(x){x.status=status;x.tries++;x.error=error;if(x.tries>=3&&status==='queued')x.status='failed'}})}}finally{sendingWa=false}}
