 function savePost(ctx,existing){const u=staff(ctx,'content_editor');const b=ctx.body,errors={};const title=str(b.title,140);if(title.length<8)errors.title='El título debe tener al menos 8 caracteres.';const slug=slugify(b.slug||title);if(!slug)errors.slug='Indica la URL.';if(db().posts.some(p=>p.slug===slug&&p.id!==existing?.id))errors.slug='Ya existe un artículo con esa URL.';if(b.cover?.key&&str(b.cover.alt,200).length<5)errors.coverAlt='La imagen de portada necesita texto alternativo.';if(str(b.metaDescription,300).length>160)errors.metaDescription='Máximo 160 caracteres.';if(str(b.seoTitle,100).length>65)errors.seoTitle='Máximo 65 caracteres.';if(b.canonical&&!/^https?:\/\/[^\s]+$/.test(b.canonical))errors.canonical='Usa una URL completa (https://…).';if(b.categoryId&&!db().categories.some(c=>c.id===b.categoryId))errors.categoryId='Selecciona una categoría.';if(Object.keys(errors).length)fail(422,'VALIDATION_ERROR','Revisa los campos marcados.',{fields:errors});
  let out;store.tx(d=>{const now=Date.now();let p=existing&&d.posts.find(x=>x.id===existing.id);if(!p){p={id:S.id('post'),status:'draft',authorId:u.id,createdAt:now,revisions:[],publishedAt:null,scheduledAt:null};d.posts.push(p)}else p.revisions.unshift({at:now,by:u.id,title:p.title,body:p.body});p.revisions=p.revisions.slice(0,20);
   if(p.slug&&p.slug!==slug&&p.status==='published'){d.redirects=d.redirects.filter(r=>r.from!==slug);d.redirects.forEach(r=>{if(r.to===p.slug)r.to=slug});d.redirects.push({from:p.slug,to:slug,at:now,by:u.id})}
   Object.assign(p,{title,slug,excerpt:str(b.excerpt,300),body:str(b.body,40000),cover:{key:str(b.cover?.key,120)||p.cover?.key||'',alt:str(b.cover?.alt,200)},categoryId:b.categoryId||null,tags:Array.isArray(b.tags)?b.tags.map(t=>str(t,40)).filter(Boolean).slice(0,8):[],seoTitle:str(b.seoTitle,65),metaDescription:str(b.metaDescription,160),canonical:str(b.canonical,300),noindex:b.noindex===true,featured:b.featured===true,updatedAt:now,updatedBy:u.id});
   if(p.featured)d.posts.forEach(x=>{if(x.id!==p.id)x.featured=false});D.audit(d,u.id,existing?'post.update':'post.create','post',p.id,{slug},ctx.requestId);out=p});return {post:adminPost(out)}}
