 route('PATCH','/api/v1/admin/blog/posts/:id',(ctx,{id})=>{const p=db().posts.find(x=>x.id===id);if(!p)fail(404,'NOT_FOUND','Artículo no encontrado.');return savePost(ctx,p)});
 route('POST','/api/v1/admin/blog/posts/:id/publish',(ctx,{id})=>{const u=staff(ctx,'content_editor');const p=db().posts.find(x=>x.id===id);if(!p)fail(404,'NOT_FOUND','Artículo no encontrado.');const action=ctx.body.action;const when=num(ctx.body.at);
  if(['publish','schedule'].includes(action)){const errors=[];if(!p.excerpt)errors.push('extracto');if(String(p.body).length<200)errors.push('texto de al menos 200 caracteres');if(!p.cover?.key)errors.push('imagen de portada');if(!p.cover?.alt)errors.push('texto alternativo');if(!p.categoryId)errors.push('categoría');if(errors.length)fail(422,'INCOMPLETE','Para publicar falta: '+errors.join(', ')+'.')}
  if(action==='schedule'&&!(when>Date.now()+60000))fail(422,'VALIDATION_ERROR','La fecha programada debe ser futura.',{fields:{at:'Elige una fecha y hora futura.'}});
  store.tx(d=>{const x=d.posts.find(v=>v.id===id);const now=Date.now();if(action==='publish'){x.status='published';x.publishedAt=x.publishedAt&&x.publishedAt<=now?x.publishedAt:now;x.scheduledAt=null;newsAlert(d,x)}else if(action==='schedule'){x.status='scheduled';x.scheduledAt=when}else if(action==='review'){x.status='review'}else if(action==='draft'){x.status='draft';x.scheduledAt=null}else if(action==='archive'){x.status='archived'}else throw new HttpError(422,'VALIDATION_ERROR','Acción no válida.');x.updatedAt=now;D.audit(d,u.id,'post.'+action,'post',id,{at:when||null},ctx.requestId)});return {post:adminPost(db().posts.find(x=>x.id===id))}});
 route('POST','/api/v1/admin/blog/media',ctx=>{const u=staff(ctx,'content_editor');const f=S.decodeUpload(ctx.body.file,{allowed:['image/png','image/jpeg','image/webp'],maxBytes:3e6});if(f.error)fail(422,'FILE_INVALID',f.error,{fields:{file:f.error}});const key=S.id('blog')+'.'+f.mime.split('/')[1];store.saveFile('publico',key,f.buffer);auditTx(u.id,'post.media_upload','media',key,{},ctx);return {key,url:D.mediaUrl(key,true)}},{maxBody:5e6});
 route('POST','/api/v1/admin/blog/categories',ctx=>{const u=staff(ctx,'content_editor');const name=str(ctx.body.name,60);if(name.length<3)fail(422,'VALIDATION_ERROR','Indica el nombre.',{fields:{name:'Indica el nombre.'}});const slug=slugify(name);if(db().categories.some(c=>c.slug===slug))fail(409,'EXISTS','Ya existe esa categoría.',{fields:{name:'Ya existe esa categoría.'}});store.tx(d=>{d.categories.push({id:S.id('cat'),name,slug,description:str(ctx.body.description,200),order:d.categories.length,active:true});D.audit(d,u.id,'category.create','category',slug,{},ctx.requestId)});return {categories:db().categories}});
